-- Orchestrator V1 PostgreSQL schema baseline
-- Apply through a migration tool in deployment; do not execute manually against production without backup.
-- UUID identifiers are generated by the application to avoid database-extension assumptions.

CREATE TABLE IF NOT EXISTS app_users (
    id UUID PRIMARY KEY,
    external_auth_subject TEXT UNIQUE NOT NULL,
    email TEXT,
    display_name TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS projects (
    id UUID PRIMARY KEY,
    owner_user_id UUID NOT NULL REFERENCES app_users(id),
    name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
    repository_url TEXT NOT NULL,
    jira_base_url TEXT,
    jira_project_key TEXT,
    archived_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_projects_owner_active ON projects(owner_user_id, archived_at);

CREATE TABLE IF NOT EXISTS project_members (
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
    access_role TEXT NOT NULL CHECK (access_role IN ('owner', 'editor', 'viewer')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id)
);

CREATE TABLE IF NOT EXISTS ai_roles (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    role_key TEXT NOT NULL CHECK (role_key IN ('project_manager', 'developer', 'qa', 'reviewer')),
    display_name TEXT NOT NULL,
    system_instructions TEXT NOT NULL DEFAULT '',
    provider_key TEXT NOT NULL DEFAULT 'unconfigured',
    model_key TEXT NOT NULL DEFAULT 'unconfigured',
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (project_id, role_key),
    UNIQUE (id, project_id)
);

CREATE TABLE IF NOT EXISTS role_chats (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    role_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (project_id, role_id),
    FOREIGN KEY (role_id, project_id) REFERENCES ai_roles(id, project_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS chat_messages (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    chat_id UUID NOT NULL REFERENCES role_chats(id) ON DELETE CASCADE,
    author_type TEXT NOT NULL CHECK (author_type IN ('user', 'assistant', 'system')),
    content TEXT NOT NULL,
    provider_key TEXT,
    model_key TEXT,
    provider_request_id TEXT,
    status TEXT NOT NULL DEFAULT 'complete' CHECK (status IN ('pending', 'complete', 'failed')),
    error_code TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (chat_id) REFERENCES role_chats(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_chat_messages_history ON chat_messages(chat_id, created_at DESC);

CREATE TABLE IF NOT EXISTS requirements (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    created_by_user_id UUID REFERENCES app_users(id),
    source_chat_id UUID NOT NULL REFERENCES role_chats(id),
    title TEXT NOT NULL,
    version INTEGER NOT NULL CHECK (version > 0),
    status TEXT NOT NULL CHECK (status IN ('draft', 'changes_requested', 'approved', 'superseded')),
    markdown_content TEXT NOT NULL,
    approved_by_user_id UUID REFERENCES app_users(id),
    approved_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (project_id, id, version),
    UNIQUE (project_id, title, version),
    CHECK ((status = 'approved' AND approved_by_user_id IS NOT NULL AND approved_at IS NOT NULL)
        OR status <> 'approved')
);

CREATE TABLE IF NOT EXISTS jira_task_links (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    requirement_id UUID NOT NULL REFERENCES requirements(id),
    jira_issue_key TEXT NOT NULL,
    jira_issue_url TEXT NOT NULL,
    summary TEXT NOT NULL,
    status_snapshot TEXT,
    last_synced_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (project_id, jira_issue_key)
);
CREATE INDEX IF NOT EXISTS idx_jira_task_project_status ON jira_task_links(project_id, status_snapshot);

CREATE TABLE IF NOT EXISTS workflow_handoffs (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    requirement_id UUID NOT NULL REFERENCES requirements(id),
    from_role_id UUID REFERENCES ai_roles(id),
    to_role_id UUID NOT NULL REFERENCES ai_roles(id),
    context_markdown TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'completed', 'failed')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS activity_events (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    actor_type TEXT NOT NULL CHECK (actor_type IN ('user', 'ai_role', 'system', 'integration')),
    actor_id UUID,
    action_key TEXT NOT NULL,
    target_type TEXT NOT NULL,
    target_id UUID,
    outcome TEXT NOT NULL CHECK (outcome IN ('started', 'succeeded', 'failed', 'rejected')),
    correlation_id UUID NOT NULL,
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_activity_project_recent ON activity_events(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_activity_correlation ON activity_events(correlation_id);

CREATE TABLE IF NOT EXISTS verification_records (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    jira_issue_key TEXT,
    check_name TEXT NOT NULL,
    result TEXT NOT NULL CHECK (result IN ('passed', 'failed', 'skipped', 'unknown')),
    evidence_url TEXT,
    commit_sha TEXT,
    pull_request_url TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS merge_records (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    jira_issue_key TEXT,
    pull_request_url TEXT NOT NULL,
    merge_commit_sha TEXT,
    merged_at TIMESTAMPTZ,
    approved_by_user_id UUID REFERENCES app_users(id),
    verified BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Security note: authorization and project membership checks must be enforced in the application
-- and/or row-level security policies before exposing any query endpoint.
